  static std::array<int, 1000> memo;
  static bool initialized = false;

  if (!initialized) {
    initialized = true;
    for (int i = 0; i < 1000; ++i) {
      memo[i] = -1; // -1 indicates an uninitialized entry.
    }
  }

  int idx = node - memo.data(); // Compute index based on node pointer.
  if (memo[idx] == -1) {
    memo[idx] = 1 + std::max(height(node->left), height(node->right));
  }
  return memo[idx];
}

int height(Node* node)
{
  if (node == nullptr)
    return 0;

  int leftHeight = height(node->left);
  int rightHeight = height(node->right);

  return 1 + std::max(leftHeight, rightHeight);
}

void quicksort(int* values, int low, int high)
{
  if (low >= high)
    return;

  // Use a sentinel to avoid modifying the caller's array.
  int* pivot = values + high;
  int* left = values + low;
  int* right = pivot - 1;

  while (left <= right) {
    // Move left while elements are less than or equal to the pivot.
    while (left <= right && *left <= *pivot) {
      ++left;
    }
    // Move right while elements are greater than the pivot.
    while (left <= right && *right > *pivot) {
      --right;
    }
    if (left <= right) {
      std::swap(*left, *right);
      ++left;
      --right;
    }
  }

  // Place the pivot in its final position.
  std::swap(*left, *pivot);

  // Recursively sort the sub‑arrays.
  quicksort(values, low, left - 1);
  quicksort(values, left + 1, high);
}

void quicksort(int* values, int low, int high)
{
  if (low >= high)
    return;

  int split = partition(values, low, high);
  if (split > low) {
    quicksort(values, low, split - 1);
  }
  if (split < high) {
    quicksort(values, split + 1, high);
  }
}

void quicksort(int* values, int low, int high)
{
  if (low >= high)
    return;

  // Use a std::vector for O(1) access and O(n) memory.
  std::vector<int> vec(values, values + high - low + 1);
  std::vector<int> sorted_vec;
  sorted_vec.reserve(vec.size());

  // Perform the partition in‑place.
  int split = partition(vec.data(), 0, vec.size() - 1);

  // Copy the partitioned elements back to the original array.
  std::copy(vec.begin(), vec.begin() + split, values + low);
  std::copy(vec.begin() + split, vec.end(), values + low + split + 1);

  // Recursively sort the two sub‑ranges.
  quicksort(values, low, split - 1);
  quicksort(values, split + 1, high);
}

void quicksort(int* values, int low, int high)
{
  if (low >= high)
    return;

  int split = partition(values, low, high);
  if (split > low)
    quicksort(values, low, split - 1);
  if (split < high)
    quicksort(values, split + 1, high);
}

void fill(int** grid, int row, int col, int from, int to)
{
  // Guard against null pointer or out‑of‑bounds access.
  if (grid == nullptr || row < 0 || col < 0 || grid[row] == nullptr || grid[row][col] != from)
    return;

  // Replace the target cell with the replacement value.
  grid[row][col] = to;

  // Recursively fill the four adjacent cells.
  fill(grid, row + 1, col, from, to);
  fill(grid, row - 1, col, from, to);
  fill(grid, row, col + 1, from, to);
  fill(grid, row, col - 1, from, to);
}

void fill(int** grid, int row, int col, int from, int to)
{
  if (row < 0 || col < 0 || !grid || !grid[row] || grid[row][col] != from)
    return;

  grid[row][col] = to;

  // Guard against out‑of‑bounds access; the original code would dereference a null pointer.
  if (row + 1 < 0 || !grid[row + 1])
    return;
  fill(grid, row + 1, col, from, to);

  if (row - 1 >= 0 && grid[row - 1])
    fill(grid, row - 1, col, from, to);

  if (col + 1 < 0 || !grid[row])
    return;
  fill(grid, row, col + 1, from, to);

  if (col - 1 >= 0 && grid[row])
    fill(grid, row, col - 1, from, to);
}

void fill(int** grid, int row, int col, int from, int to)
{
  // Guard against null pointer or out‑of‑bounds access.
  if (!grid || row < 0 || col < 0 || !grid[row] || grid[row][col] != from)
    return;

  // Store the original value for later restoration.
  const int original = grid[row][col];

  // Replace the target cell with the replacement value.
  grid[row][col] = to;

  // Recursively fill the four adjacent cells.
  fill(grid, row + 1, col, from, to);
  fill(grid, row - 1, col, from, to);
  fill(grid, row, col + 1, from, to);
  fill(grid, row, col - 1, from, to);

  // Restore the original value to preserve the original grid.
  grid[row][col] = original;
}

void fill(int** grid, int row, int col, int from, int to)
{
  if (row < 0 || col < 0 || !grid[row] || grid[row][col] != from)
    return;

  grid[row][col] = to;

  // Fill adjacent cells using a loop to avoid recursion overhead
  for (int dr = -1; dr <= 1; ++dr)
  {
    for (int dc = -1; dc <= 1; ++dc)
    {
      int newRow = row + dr;
      int newCol = col + dc;
      if (newRow >= 0 && newCol >= 0 && newRow < static_cast<int>(std::size(grid)) && newCol < static_cast<int>(std::size(grid[0])) && grid[newRow][newCol] == from)
      {
        fill(grid, newRow, newCol, from, to);
      }
    }
  }
}
